import * as React from "react";
import { createI18n, getInitialLocale, LOCALES } from "../i18n/index.js";
import { RECORDING_UI } from "../i18n/recordings.js";
import {
  advancePlayback,
  formatPosition,
  parsePosition,
} from "../recordings/playback.js";
import { createDsaImage } from "../recordings/rendering.js";
import {
  DEFAULT_REFERENCE_PROFILE,
  REFERENCE_PROFILES,
  getReferenceSpectrumView,
  normalizeReferenceSettings,
} from "../recordings/referenceProfiles.js";
import {
  clampTimelinePosition,
  normalizeSelection,
} from "../recordings/timeline.js";
import { loadPresentationAssets } from "../recordings/presentation.js";
import { createRecordingExportScene } from "./RecordingExportScene.jsx";
import { svgToPdf } from "../recordings/vectorPdf.js";
import {
  canvasToPng,
  canvasToPdf,
  exportVideo,
  getSupportedVideoFormats,
  saveExport,
} from "../recordings/export.js";
import RecordingTimeline from "./RecordingTimeline.jsx";
import RecordingPresentation from "./RecordingPresentation.jsx";
import {
  MAX_CASE_FILE_BYTES,
  createDefaultCaseState,
  encodeCaseFile,
  caseDownloadName,
} from "../recordings/caseFile.js";
import "../styles/recordings.css";

export default function RecordingPlayer({
  onClose,
  demoFileFactory,
  onLoaded,
  suiteLocale = null,
  previewCopy,
}) {
  const [selectedLocale, setLocale] = React.useState(() =>
    demoFileFactory ? "fr" : getInitialLocale(),
  );
  const locale = suiteLocale ?? selectedLocale;
  const { t, displayViews } = React.useMemo(() => createI18n(locale), [locale]);
  const [data, setData] = React.useState(null);
  const [isDemo, setIsDemo] = React.useState(false);
  const [referenceProfile, setReferenceProfile] = React.useState(
    DEFAULT_REFERENCE_PROFILE,
  );
  const [busy, setBusy] = React.useState(false);
  const [error, setError] = React.useState(null);
  const [position, setPosition] = React.useState(0);
  const [playing, setPlaying] = React.useState(false);
  const [speed, setSpeed] = React.useState(1);
  const [selection, setSelection] = React.useState({ start: 0, end: 0 });
  const [selectionText, setSelectionText] = React.useState({
    start: "0:00",
    end: "0:00",
  });
  const [selectionError, setSelectionError] = React.useState(false);
  const [eegWindow, setEegWindow] = React.useState(4);
  const [eegMotion, setEegMotion] = React.useState("sweep");
  const [amplitude, setAmplitude] = React.useState(120);
  const [dsaWindow, setDsaWindow] = React.useState(0);
  const [colorOffset, setColorOffset] = React.useState(0);
  const [guides, setGuides] = React.useState(true);
  const [sef50, setSef50] = React.useState(false);
  const [sef95, setSef95] = React.useState(false);
  const [layout, setLayout] = React.useState("simulator-frame");
  const [monitorView, setMonitorView] = React.useState("eeg-dsa");
  const [eventMarkers, setEventMarkers] = React.useState([]);
  const [timelineOptions, setTimelineOptions] = React.useState({
    showIndices: true,
    hiddenIndices: [],
  });
  const [assets, setAssets] = React.useState(null);
  const [exporting, setExporting] = React.useState(null);
  const [exportProgress, setExportProgress] = React.useState(0);
  const [exportError, setExportError] = React.useState(null);
  const videoFormats = React.useMemo(() => getSupportedVideoFormats(), []);
  const [videoType, setVideoType] = React.useState(
    () => videoFormats[0]?.mimeType || "",
  );
  const workerRef = React.useRef(null);
  const requestRef = React.useRef(0);
  const positionRef = React.useRef(0);
  const fileInputRef = React.useRef(null);
  const sourceBlobRef = React.useRef(null);
  const sourceNameRef = React.useRef("");
  const exportAbortRef = React.useRef(null);
  const exportRequestRef = React.useRef(0);
  const locked = busy || Boolean(exporting);

  React.useEffect(() => {
    let active = true;
    loadPresentationAssets(import.meta.env.BASE_URL)
      .then((loaded) => {
        if (active) setAssets(loaded);
      })
      .catch(() => {
        if (active) setAssets({});
      });
    return () => {
      active = false;
    };
  }, []);

  React.useEffect(() => {
    localStorage.setItem("conox.locale", locale);
    document.documentElement.lang = locale;
  }, [locale]);
  React.useEffect(
    () => () => {
      requestRef.current++;
      workerRef.current?.terminate();
      exportRequestRef.current++;
      exportAbortRef.current?.abort();
    },
    [],
  );

  const cancelLoad = () => {
    requestRef.current++;
    workerRef.current?.terminate();
    workerRef.current = null;
    setBusy(false);
  };
  const seek = (value) => {
    const next = clampTimelinePosition(
      value,
      data?.recording.durationSeconds || 0,
    );
    setPlaying(false);
    positionRef.current = next;
    setPosition(next);
  };
  const togglePlaying = () => {
    if (locked || selectionError || !data) return;
    if (
      !playing &&
      (positionRef.current >= selection.end ||
        positionRef.current < selection.start)
    )
      seek(selection.start);
    setPlaying(!playing);
  };
  const changeSettings = (next) => {
    if (locked) return;
    if (next.referenceProfile && next.referenceProfile !== referenceProfile) {
      const profile = next.referenceProfile;
      const restoredState = {
        referenceProfile: profile,
        locale,
        position: positionRef.current,
        speed,
        selection,
        layout,
        settings: normalizeReferenceSettings(settings, profile),
        markers: eventMarkers,
        timeline: timelineOptions,
        videoFormat:
          videoFormats.find((format) => format.mimeType === videoType)
            ?.extension || null,
      };
      loadFile(new File([sourceBlobRef.current], sourceNameRef.current), {
        referenceProfile: profile,
        restoredState,
        isDemo,
      });
      return;
    }
    const setters = {
      eegMotion: setEegMotion,
      eegWindow: setEegWindow,
      amplitude: setAmplitude,
      dsaWindow: setDsaWindow,
      colorOffset: setColorOffset,
      guides: setGuides,
      sef50: setSef50,
      sef95: setSef95,
      monitorView: setMonitorView,
    };
    Object.entries(next).forEach(([key, value]) => setters[key]?.(value));
  };
  const setPassage = (next) => {
    setSelection(next);
    setSelectionText({
      start: formatPosition(next.start, true),
      end: formatPosition(next.end, true),
    });
    setSelectionError(false);
    setPlaying(false);
  };
  const commitPassage = () => {
    const start = parsePosition(selectionText.start);
    const end = parsePosition(selectionText.end);
    if (
      start === null ||
      end === null ||
      start >= end ||
      end - start < Math.min(0.25, data.recording.durationSeconds) ||
      end > data.recording.durationSeconds
    ) {
      setSelectionError(true);
      return;
    }
    setPassage({ start, end });
  };
  const loadFile = async (file, options = {}) => {
    if (!file) return;
    cancelLoad();
    setPlaying(false);
    setError(null);
    setExportError(null);
    if (file.size > MAX_CASE_FILE_BYTES) {
      setError("TOO_LARGE");
      return;
    }
    setBusy(true);
    const request = ++requestRef.current;
    try {
      const buffer = await file.arrayBuffer();
      if (request !== requestRef.current) return;
      // Snapshot bytes before transferring the buffer. Saving must not depend on
      // the original file still existing or remaining unchanged on disk.
      const sourceSnapshot = new Blob([buffer], {
        type: "application/octet-stream",
      });
      const worker = new Worker(
        new URL("../recordings/recording.worker.js", import.meta.url),
        { type: "module" },
      );
      workerRef.current = worker;
      const fail = (code) => {
        if (request !== requestRef.current) return;
        worker.terminate();
        workerRef.current = null;
        setBusy(false);
        setError(code);
      };
      worker.onerror = () => fail("UNKNOWN");
      worker.onmessage = ({ data: result }) => {
        if (request !== requestRef.current) return;
        if (result.error) {
          fail(result.error);
          return;
        }
        worker.terminate();
        workerRef.current = null;
        const restored =
          options.restoredState ||
          result.session ||
          createDefaultCaseState(
            result.recording.durationSeconds,
            locale,
            result.referenceProfile,
          );
        sourceBlobRef.current = sourceSnapshot.slice(
          0,
          result.sourceByteLength,
        );
        sourceNameRef.current = result.sourceName;
        setData(result);
        setIsDemo(Boolean(options.isDemo));
        onLoaded?.();
        setReferenceProfile(result.referenceProfile);
        setLocale(restored.locale);
        positionRef.current = restored.position;
        setPosition(restored.position);
        setSpeed(restored.speed);
        setPassage(restored.selection);
        setLayout(restored.layout);
        setEegWindow(restored.settings.eegWindow);
        setEegMotion(restored.settings.eegMotion);
        setAmplitude(restored.settings.amplitude);
        setDsaWindow(restored.settings.dsaWindow);
        setColorOffset(restored.settings.colorOffset);
        setGuides(restored.settings.guides);
        setSef50(restored.settings.sef50);
        setSef95(restored.settings.sef95);
        setMonitorView(restored.settings.monitorView);
        setEventMarkers(restored.markers);
        setTimelineOptions(restored.timeline);
        setVideoType(
          (
            videoFormats.find(
              (format) => format.extension === restored.videoFormat,
            ) || videoFormats[0]
          )?.mimeType || "",
        );
        setBusy(false);
      };
      worker.postMessage(
        {
          buffer,
          fileName: file.name,
          referenceProfile: options.referenceProfile,
          defaultReferenceProfile: referenceProfile,
        },
        [buffer],
      );
    } catch {
      if (request === requestRef.current) {
        setBusy(false);
        setError("UNKNOWN");
      }
    }
  };

  React.useEffect(() => {
    if (!playing || !data) return;
    let previous = performance.now();
    const timer = window.setInterval(() => {
      const now = performance.now();
      const next = advancePlayback(
        positionRef.current,
        (now - previous) / 1000,
        speed,
        selection.start,
        selection.end,
      );
      previous = now;
      positionRef.current = next.position;
      setPosition(next.position);
      if (next.ended) setPlaying(false);
    }, 40);
    // Do not jump through a teaching passage when the browser goes into the background.
    const pauseWhenHidden = () => {
      if (document.hidden) setPlaying(false);
    };
    document.addEventListener("visibilitychange", pauseWhenHidden);
    return () => {
      window.clearInterval(timer);
      document.removeEventListener("visibilitychange", pauseWhenHidden);
    };
  }, [playing, data, speed, selection]);

  const presentationData = React.useMemo(
    () =>
      data
        ? {
            ...data,
            spectrum: getReferenceSpectrumView(data.spectrum, dsaWindow),
          }
        : null,
    [data, dsaWindow],
  );
  const dsaImage = React.useMemo(
    () =>
      presentationData
        ? createDsaImage(presentationData.spectrum, colorOffset, position)
        : null,
    [presentationData, colorOffset, Math.floor(position * 4)],
  );
  const settings = React.useMemo(
    () => ({
      referenceProfile,
      eegMotion,
      eegWindow,
      amplitude,
      dsaWindow,
      colorOffset,
      guides,
      sef50,
      sef95,
      monitorView,
    }),
    [
      referenceProfile,
      eegMotion,
      eegWindow,
      amplitude,
      dsaWindow,
      colorOffset,
      guides,
      sef50,
      sef95,
      monitorView,
    ],
  );

  const startExport = async (kind) => {
    if (!data || locked || assets === null) return;
    if (kind === "video" && selectionError) return;
    setPlaying(false);
    setExportError(null);
    setExportProgress(0);
    setExporting(kind);
    const request = ++exportRequestRef.current;
    const controller = new AbortController();
    exportAbortRef.current = controller;
    const exportPosition = positionRef.current;
    const scene = createRecordingExportScene({
      data: presentationData,
      dsaImage,
      settings,
      layout,
      t,
      assets,
      displayViews,
      signal: controller.signal,
    });
    const { canvas, renderFrame } = scene;
    try {
      await renderFrame(exportPosition);
      let blob;
      let extension = kind === "pdf" ? "pdf" : "png";
      if (kind === "video") {
        extension = videoFormats.find(
          (format) => format.mimeType === videoType,
        )?.extension;
        if (!extension) throw { code: "UNSUPPORTED_VIDEO" };
        blob = await exportVideo({
          canvas,
          renderFrame,
          start: selection.start,
          end: selection.end,
          speed,
          mimeType: videoType,
          onProgress: setExportProgress,
          signal: controller.signal,
        });
      } else
        blob =
          kind === "pdf"
            ? layout === "blocks"
              ? await svgToPdf(scene.element)
              : await canvasToPdf(canvas)
            : await canvasToPng(canvas);
      if (controller.signal.aborted || request !== exportRequestRef.current)
        return;
      const at =
        kind === "video"
          ? `${formatPosition(selection.start, true)}-${formatPosition(selection.end, true)}`
          : formatPosition(exportPosition, true);
      saveExport(
        blob,
        `CONOX-${layout}-${at.replaceAll(":", "m").replaceAll(".", "-")}.${extension}`,
      );
    } catch (failure) {
      if (
        request === exportRequestRef.current &&
        failure.code !== "EXPORT_ABORTED"
      )
        setExportError(failure.code || "EXPORT_FAILED");
    } finally {
      scene.dispose();
      if (request === exportRequestRef.current) {
        setExporting(null);
        exportAbortRef.current = null;
      }
    }
  };

  const saveCase = async (originalOnly = false) => {
    if (
      !data ||
      !sourceBlobRef.current ||
      locked ||
      (!originalOnly && selectionError)
    )
      return;
    setPlaying(false);
    setExportError(null);
    setExporting("case");
    const request = ++exportRequestRef.current;
    const source = sourceBlobRef.current;
    const name = sourceNameRef.current;
    try {
      const blob = originalOnly
        ? source
        : await encodeCaseFile(
            await source.arrayBuffer(),
            {
              referenceProfile,
              locale,
              position: positionRef.current,
              speed,
              selection,
              layout,
              settings,
              markers: eventMarkers,
              timeline: timelineOptions,
              videoFormat:
                videoFormats.find((format) => format.mimeType === videoType)
                  ?.extension || null,
            },
            { duration: data.recording.durationSeconds, sourceName: name },
          );
      if (request !== exportRequestRef.current) return;
      saveExport(blob, originalOnly ? name : caseDownloadName(name));
    } catch {
      if (request === exportRequestRef.current)
        setExportError("CASE_EXPORT_FAILED");
    } finally {
      if (request === exportRequestRef.current) setExporting(null);
    }
  };

  const loadDemo = async () => {
    if (locked) return;
    setBusy(true);
    const request = ++requestRef.current;
    try {
      const file = await demoFileFactory();
      if (request === requestRef.current)
        await loadFile(file, { isDemo: true });
    } catch {
      if (request === requestRef.current) {
        setBusy(false);
        setError("UNKNOWN");
      }
    }
  };
  const recording = data?.recording;
  const errorText =
    error &&
    (RECORDING_UI[locale][`recording.error.${error}`] || t("recording.error"));
  return (
    <main
      lang={locale}
      className={`sb-shell recording-shell${recording ? " has-recording" : ""}`}
    >
      <header className="sb-header recording-header">
        <div>
          <strong>{t("recording.title")}</strong>
          <small>{t("recording.local")}</small>
        </div>
        <div className="recording-header-tools">
          <div className="sb-language-switch" aria-label="Language">
            {LOCALES.map((item) => (
              <button
                key={item.code}
                type="button"
                className={locale === item.code ? "active" : ""}
                disabled={Boolean(exporting)}
                aria-pressed={locale === item.code}
                onClick={() => setLocale(item.code)}
              >
                {item.label}
              </button>
            ))}
          </div>
          <button
            type="button"
            className="sb-btn"
            title={t("recording.backNote")}
            onClick={onClose}
          >
            {t("recording.back")}
          </button>
        </div>
      </header>
      <div className="recording-content">
        {!recording && (
          <p className="recording-notice">{t("recording.experimental")}</p>
        )}
        <div className="recording-filebar">
          <button
            type="button"
            className="sb-btn"
            disabled={locked}
            onClick={() => fileInputRef.current.click()}
          >
            {t(recording ? "recording.replace" : "recording.choose")}
          </button>
          {demoFileFactory && !recording && (
            <button
              type="button"
              className="sb-btn lab-demo-button"
              onClick={loadDemo}
              disabled={locked}
            >
              {previewCopy.tryDemo}
            </button>
          )}
          {recording && isDemo && (
            <span className="lab-demo-label">{previewCopy.demoLabel}</span>
          )}
          <input
            ref={fileInputRef}
            type="file"
            accept=".cxbin"
            hidden
            aria-label={t("recording.choose")}
            onChange={(event) => {
              loadFile(event.target.files[0]);
              event.target.value = "";
            }}
          />
          {busy && (
            <>
              <span role="status">{t("recording.loading")}</span>
              <button type="button" className="sb-btn" onClick={cancelLoad}>
                {t("recording.cancel")}
              </button>
            </>
          )}
          {!recording && (
            <label className="recording-inline-field">
              {t("reference.profile")}
              <select
                value={referenceProfile}
                disabled={locked}
                aria-label={t("reference.profile")}
                onChange={(event) => setReferenceProfile(event.target.value)}
              >
                {Object.values(REFERENCE_PROFILES).map((profile) => (
                  <option key={profile.id} value={profile.id}>
                    {profile.name}
                  </option>
                ))}
              </select>
            </label>
          )}
          {recording && (
            <>
              <button
                type="button"
                className="sb-btn recording-save-case"
                disabled={locked || selectionError}
                title={t("recording.caseSaveHelp")}
                onClick={() => saveCase()}
              >
                {t("recording.caseSave")}
              </button>
              <span
                className="recording-provisional"
                title={t("recording.experimentalShort")}
              >
                {t("recording.provisional")}
              </span>
              <details className="recording-file-details">
                <summary>{t("recording.fileDetails")}</summary>
                <div className="recording-file-details-body">
                  <p className="recording-file-name">
                    {recording.fileName} · {t("recording.duration")}:{" "}
                    {formatPosition(recording.durationSeconds)}
                  </p>
                  <p className="recording-meta">
                    {recording.id} · {t("recording.date")}:{" "}
                    {recording.startedAt?.replace("T", " ")}
                  </p>
                  <p className="recording-notice">
                    {t("recording.experimental")}
                  </p>
                  <p>{t("recording.caseSaveHelp")}</p>
                  <p>{t("recording.caseCompatibility")}</p>
                  <p>{t(`recording.impedanceHelp.${referenceProfile}`)}</p>
                  <p>{t(`recording.referenceSource.${referenceProfile}`)}</p>
                  <p>
                    {t("recording.integrity", {
                      count: recording.integrity.checkedFrames,
                    })}
                  </p>
                  <button
                    type="button"
                    className="sb-btn"
                    disabled={locked}
                    onClick={() => saveCase(true)}
                  >
                    {t("recording.caseOriginal")}
                  </button>
                  <div className="recording-warnings" role="status">
                    {recording.warnings
                      .filter(
                        (warning) => warning.code !== "experimentalDecoding",
                      )
                      .map((warning) => (
                        <p key={warning.code}>
                          {t(`recording.warning.${warning.code}`, warning)}
                        </p>
                      ))}
                  </div>
                </div>
              </details>
            </>
          )}
        </div>
        {error && (
          <p className="recording-error" role="alert">
            {errorText}
          </p>
        )}
        {!recording && !busy && (
          <div className="recording-empty">
            {demoFileFactory ? (
              <>
                <span className="lab-empty-kicker">
                  {previewCopy.emptyKicker}
                </span>
                <h2>{previewCopy.emptyTitle}</h2>
                <p>{previewCopy.emptyDescription}</p>
                <div className="lab-empty-steps">
                  <span>
                    <b>01</b> {previewCopy.emptySteps[0]}
                  </span>
                  <span>
                    <b>02</b> {previewCopy.emptySteps[1]}
                  </span>
                  <span>
                    <b>03</b> {previewCopy.emptySteps[2]}
                  </span>
                </div>
                <small>{previewCopy.emptyLocal}</small>
              </>
            ) : (
              t("recording.empty")
            )}
          </div>
        )}
        {recording && (
          <>
            <fieldset className="recording-controls" disabled={locked}>
              <legend>{t("recording.toolbar")}</legend>
              <div className="recording-toolbar-row">
                <div className="recording-transport">
                  <button
                    type="button"
                    className="sb-btn recording-play"
                    disabled={selectionError}
                    aria-pressed={playing}
                    onClick={togglePlaying}
                  >
                    {t(playing ? "recording.pause" : "recording.play")}
                  </button>
                  <button
                    type="button"
                    className="sb-btn"
                    onClick={() => seek(selection.start)}
                  >
                    {t("recording.restart")}
                  </button>
                  <label className="recording-inline-field">
                    {t("recording.speedShort")}
                    <select
                      value={speed}
                      aria-label={t("recording.speed")}
                      onChange={(event) => setSpeed(Number(event.target.value))}
                    >
                      {[0.25, 0.5, 1, 2, 3, 4].map((value) => (
                        <option key={value} value={value}>
                          {value}×
                        </option>
                      ))}
                    </select>
                  </label>
                  <output data-testid="recording-time">
                    {formatPosition(position, true)} /{" "}
                    {formatPosition(recording.durationSeconds)}
                  </output>
                </div>
                <fieldset
                  className="recording-export-actions"
                  disabled={assets === null}
                  aria-label={t("recording.export")}
                >
                  <button
                    type="button"
                    className="sb-btn"
                    aria-label={t("recording.exportImage")}
                    title={t("recording.exportImage")}
                    onClick={() => startExport("image")}
                  >
                    PNG
                  </button>
                  <button
                    type="button"
                    className="sb-btn"
                    aria-label={t("recording.exportPdf")}
                    title={t("recording.exportPdf")}
                    onClick={() => startExport("pdf")}
                  >
                    PDF
                  </button>
                  <button
                    type="button"
                    className="sb-btn"
                    aria-label={t("recording.exportVideo")}
                    title={
                      videoFormats.length
                        ? t("recording.exportVideo")
                        : t("recording.exportUnsupported")
                    }
                    disabled={!videoFormats.length || selectionError}
                    onClick={() => startExport("video")}
                  >
                    {t("recording.videoShort")}
                  </button>
                </fieldset>
              </div>
              <RecordingTimeline
                duration={recording.durationSeconds}
                frames={recording.frames}
                markers={eventMarkers}
                onMarkersChange={setEventMarkers}
                timelineOptions={timelineOptions}
                onTimelineOptionsChange={setTimelineOptions}
                position={position}
                selection={selection}
                onSeek={seek}
                onSelectionChange={(value) =>
                  setPassage(
                    normalizeSelection(value, recording.durationSeconds),
                  )
                }
                disabled={locked}
                t={t}
              />
              <div className="recording-toolbar-row recording-toolbar-secondary">
                <div className="recording-passage">
                  {[
                    ["start", "recording.start"],
                    ["end", "recording.end"],
                  ].map(([key, label]) => (
                    <label key={key} className="recording-inline-field">
                      {t(label)}
                      <input
                        type="text"
                        value={selectionText[key]}
                        aria-invalid={selectionError}
                        onChange={(event) =>
                          setSelectionText((current) => ({
                            ...current,
                            [key]: event.target.value,
                          }))
                        }
                        onBlur={commitPassage}
                        onKeyDown={(event) => {
                          if (event.key === "Enter") commitPassage();
                        }}
                      />
                    </label>
                  ))}
                  <button
                    type="button"
                    className="sb-btn"
                    onClick={() =>
                      setPassage({ start: 0, end: recording.durationSeconds })
                    }
                  >
                    {t("recording.fullCase")}
                  </button>
                </div>
                {videoFormats.length > 0 && (
                  <label className="recording-inline-field recording-video-format">
                    {t("recording.videoFormat")}
                    <select
                      aria-label={t("recording.videoFormat")}
                      value={videoType}
                      disabled={assets === null}
                      onChange={(event) => setVideoType(event.target.value)}
                    >
                      {videoFormats.map((format) => (
                        <option key={format.mimeType} value={format.mimeType}>
                          {format.label}
                        </option>
                      ))}
                    </select>
                  </label>
                )}
                <details className="recording-help-details">
                  <summary>{t("recording.helpShort")}</summary>
                  <div className="recording-help-body">
                    <p>{t("recording.selectionNote")}</p>
                    <p>{t("recording.exportViewNote")}</p>
                    <p>
                      {videoFormats.length
                        ? t("recording.videoNote", {
                            duration: formatPosition(
                              (selection.end - selection.start) / speed,
                            ),
                          })
                        : t("recording.exportUnsupported")}
                    </p>
                  </div>
                </details>
              </div>
              {selectionError && (
                <p className="recording-error" role="alert">
                  {t("recording.invalidSelection")}
                </p>
              )}
            </fieldset>
            {exporting && (
              <div className="recording-export-progress" role="status">
                <span>
                  {t(
                    exporting === "video"
                      ? "recording.exportingVideo"
                      : "recording.exportingImage",
                    { count: Math.round(exportProgress * 100) },
                  )}
                </span>
                {exporting === "video" && (
                  <>
                    <progress
                      max={1}
                      value={exportProgress}
                      aria-label={t("recording.exportProgress")}
                    />
                    <button
                      type="button"
                      className="sb-btn"
                      onClick={() => exportAbortRef.current?.abort()}
                    >
                      {t("recording.cancel")}
                    </button>
                  </>
                )}
              </div>
            )}
            {exportError && (
              <p className="recording-error" role="alert">
                {t(
                  `recording.exportError.${["EXPORT_FAILED", "EXPORT_HIDDEN", "UNSUPPORTED_VIDEO", "CASE_EXPORT_FAILED"].includes(exportError) ? exportError : "EXPORT_FAILED"}`,
                )}
              </p>
            )}
            <RecordingPresentation
              data={presentationData}
              dsaImage={dsaImage}
              position={position}
              settings={settings}
              layout={layout}
              t={t}
              displayViews={displayViews}
              playing={playing}
              onTogglePlaying={togglePlaying}
              onSeek={seek}
              locked={locked}
              onSettingsChange={changeSettings}
              onLayoutChange={setLayout}
            />
          </>
        )}
      </div>
    </main>
  );
}
